mapper.select:
select o.id, o.order_no, o.user_id, o.merchant_id, o.total_amount, o.total_calorie,
       o.order_type, o.status, o.pickup_code, o.pay_time, o.accept_time, o.finish_time,
       o.remark, o.create_time, o.update_time,
       u.nickname userNickname, m.name merchantName
from orders o
    left join user u on o.user_id = u.id
    left join merchant m on o.merchant_id = m.id


        o.user_id = #{userId}


        and o.merchant_id = #{merchantId}


        and o.status = #{status}


        and o.order_type = #{orderType}


order by o.create_time desc, o.id desc

mapper.update:
update orders
status = #{status}, update_time = #{updateTime}, pickup_code = #{pickupCode}, accept_time = #{acceptTime}, finish_time = #{finishTime},
where id = #{id}
